//! Shared ML-DSA response state machine: splice generated bytes and a certificate into small framing
//! bytes. Classic primitive, framing and CryptoScratch views alias the sole
//! session workspace; no product storage layout or command state lives here.
use crate::provision::PRIVATE_KEY_BYTES;
use crate::signing::{DIGEST_BYTES, MAX_ES256_SIGNATURE_BYTES, RAW_SIGNATURE_BYTES};
use canokey_ports::{
    Backends, Crypto as _, CryptoScratch, Device as _, DigestOperation as Hash, HashState,
    Memory as _, Platform, StreamOperation as Op, alg,
};
use canokey_protocol::{cbor::Encoder, der::der_signature, response::StatusWord as Sw};

pub mod reply;

/// Static product material/error projections. Algorithm admission and ordinary
/// attestation fallback run before this strict streaming engine is entered.
/// These calls borrow existing capabilities; they cannot retain a workspace.
pub trait Profile<B: Backends> {
    type Error;
    fn invalid() -> Self::Error;
    fn cancelled() -> Self::Error;
    fn key(
        output: &mut [u8; DIGEST_BYTES],
        platform: &mut Platform<'_, B>,
    ) -> Result<(), Self::Error>;
    fn certificate(
        offset: u32,
        output: &mut [u8],
        platform: &mut Platform<'_, B>,
    ) -> Result<(), Sw>;
}

// Bounded envelope storage, excluding streamed public key/signature/certificate.
// stage() checks prefix + tail + assertion authData against this workspace slice.
pub const FRAMING_BYTES: usize = 768;
const MATERIAL_BYTES: usize = DIGEST_BYTES + canokey_ports::mldsa::SEED_BYTES;
const PUBLIC_HASH_WINDOW_BYTES: usize = 128;
// RFC 8949: byte-string lengths below 24 are encoded in the initial byte.
const CBOR_INLINE_LENGTH_LIMIT: usize = 24;
#[derive(Clone, Copy)]
pub enum Mode {
    Make,
    Assert,
    Public,
}
#[derive(Clone, Copy)]
pub struct Pending {
    pub algorithm: u8,
    pub mode: Mode,
    pub prefix: usize,
    pub auth: usize,
    pub public_at: usize,
    pub signature_at: usize,
    pub certificate: Option<(usize, usize)>,
    pub output: usize,
    pub hash_prefix: (usize, usize),
    pub hash_suffix: (usize, usize),
}
// Framing survives primitive initialization, but never aliases its opaque state.
#[repr(C)]
pub struct Framing {
    algorithm: u8,
    length: usize,
    generated_at: usize,
    generated_length: usize,
    certificate_at: usize,
    certificate_length: usize,
    emitted: usize,
    // clientDataHash followed by the ML-DSA seed, matching classic input.
    material: [u8; MATERIAL_BYTES],
    pub bytes: [u8; FRAMING_BYTES],
}
impl Framing {
    pub const fn new() -> Self {
        Self {
            algorithm: alg::P256,
            bytes: [0x00; FRAMING_BYTES],
            length: 0,
            material: [0x00; MATERIAL_BYTES],
            generated_at: 0,
            generated_length: 0,
            certificate_at: 0,
            certificate_length: 0,
            emitted: 0,
        }
    }
    #[inline(never)]
    pub fn clear(&mut self, memory: &(impl canokey_ports::Memory + ?Sized)) {
        memory.wipe(&mut self.bytes);
        memory.wipe(&mut self.material);
        self.algorithm = alg::P256;
        self.length = 0;
        self.generated_at = 0;
        self.generated_length = 0;
        self.certificate_at = 0;
        self.certificate_length = 0;
        self.emitted = 0;
    }
    /// Stage existing classic input before its owner erases and replaces the
    /// primitive. The framing buffer already contains the prepared wire bytes.
    /// Pending offsets and input lengths come from the admitted response builder;
    /// they are internal workspace metadata, never unvalidated wire values.
    #[inline(always)]
    pub fn stage(
        &mut self,
        plan: Pending,
        input: &[u8],
        memory: &(impl canokey_ports::Memory + ?Sized),
    ) -> Result<canokey_ports::mldsa::Parameters, ()> {
        let params = canokey_ports::mldsa::parameters(plan.algorithm).ok_or(())?;
        if plan.output + plan.auth > FRAMING_BYTES {
            return Err(());
        }
        self.bytes
            .copy_within(plan.prefix..plan.output, plan.prefix + plan.auth);
        self.bytes[plan.prefix..plan.prefix + plan.auth].copy_from_slice(&input[..plan.auth]);
        self.material
            .copy_from_slice(&input[plan.auth..plan.auth + MATERIAL_BYTES]);
        self.length = plan.output + plan.auth;
        memory.wipe(&mut self.bytes[self.length..]);
        Ok(params)
    }
    /// Called after classic key/input erasure and primitive replacement. Seed
    /// staging is erased by prepare on every exit, including failed init.
    #[inline(always)]
    pub fn activate(&mut self, plan: Pending, params: canokey_ports::mldsa::Parameters) {
        self.algorithm = plan.algorithm;
        self.generated_at = match plan.mode {
            Mode::Make | Mode::Public => plan.public_at,
            Mode::Assert => plan.signature_at + plan.auth,
        };
        self.generated_length = if matches!(plan.mode, Mode::Assert) {
            params.signature_bytes
        } else {
            params.public_bytes
        };
        self.certificate_at = plan.certificate.map_or(self.length, |(at, _)| at);
        self.certificate_length = plan.certificate.map_or(0, |(_, length)| length);
        self.emitted = 0;
    }
    pub const fn length(&self) -> usize {
        self.length
    }
    pub const fn emitted(&self) -> usize {
        self.emitted
    }
    pub fn material(&self) -> &[u8; MATERIAL_BYTES] {
        &self.material
    }
}
pub struct Stream<'a> {
    pub crypto: &'a mut CryptoScratch,
    pub framing: &'a mut Framing,
}
enum PartSource {
    Framing(usize),
    Generated,
    Certificate,
}
struct Part {
    source: PartSource,
    length: usize,
}
impl Stream<'_> {
    fn parameters(&self) -> canokey_ports::mldsa::Parameters {
        // stage() validates the selected algorithm before activate() installs it.
        canokey_ports::mldsa::parameters(self.framing.algorithm).unwrap()
    }
    pub fn prepare<P: Profile<B>, B: Backends>(
        &mut self,
        plan: Pending,
        p: &mut Platform<'_, B>,
    ) -> Result<usize, P::Error> {
        let result = self.initialize::<P, B>(plan, p);
        p.memory.wipe(&mut self.framing.material);
        if result.is_err() {
            self.close(p);
        }
        result.map(|()| self.len())
    }
    fn init<P: Profile<B>, B: Backends>(
        &mut self,
        op: Op,
        p: &mut Platform<'_, B>,
    ) -> Result<usize, P::Error> {
        p.device.keepalive(false);
        p.crypto
            .stream(
                op,
                self.framing.algorithm,
                self.crypto,
                &self.framing.material[DIGEST_BYTES..],
                &mut [],
            )
            .map_err(|_| P::invalid())
    }
    fn initialize<P: Profile<B>, B: Backends>(
        &mut self,
        plan: Pending,
        p: &mut Platform<'_, B>,
    ) -> Result<(), P::Error> {
        match plan.mode {
            Mode::Make => self.initialize_make::<P, B>(plan, p)?,
            Mode::Assert => {
                self.init::<P, B>(Op::SignInit, p)?;
                p.crypto
                    .stream(
                        Op::SignUpdate,
                        self.framing.algorithm,
                        self.crypto,
                        &self.framing.bytes[plan.prefix..plan.prefix + plan.auth],
                        &mut [],
                    )
                    .map_err(|_| P::invalid())?;
                p.crypto
                    .stream(
                        Op::SignUpdate,
                        self.framing.algorithm,
                        self.crypto,
                        &self.framing.material[..DIGEST_BYTES],
                        &mut [],
                    )
                    .map_err(|_| P::invalid())?;
                if p.crypto
                    .stream(
                        Op::SignFinal,
                        self.framing.algorithm,
                        self.crypto,
                        &[],
                        &mut [],
                    )
                    .map_err(|_| P::invalid())?
                    != self.parameters().signature_bytes
                {
                    return Err(P::invalid());
                }
            }
            Mode::Public => {
                if self.init::<P, B>(Op::PublicInit, p)? != self.parameters().public_bytes {
                    return Err(P::invalid());
                }
            }
        }
        Ok(())
    }
    // Registration-only hash/signature temporaries must not remain live on
    // the ML-DSA assertion signing path.
    #[inline(never)]
    fn initialize_make<P: Profile<B>, B: Backends>(
        &mut self,
        plan: Pending,
        p: &mut Platform<'_, B>,
    ) -> Result<(), P::Error> {
        if self.init::<P, B>(Op::PublicInit, p)? != self.parameters().public_bytes {
            return Err(P::invalid());
        }
        // The stream API exposes public bytes only while the primitive
        // is open. Close it after hashing the first public view, then
        // reopen it to emit the response; retaining a second full public-key
        // copy would exceed the shared workspace budget.
        let mut hash = HashState {
            bytes: [0x00; canokey_ports::HASH_STATE_BYTES],
        };
        let digest_result = self.attestation_digest::<P, B>(plan, &mut hash, p);
        let _ = p.crypto.digest(Hash::Abort, &mut hash, &[], &mut []);
        let _ = p
            .crypto
            .stream(Op::Abort, self.framing.algorithm, self.crypto, &[], &mut []);
        let digest = digest_result?;
        self.attest::<P, B>(plan.signature_at + plan.auth, &digest, p)?;
        if self.init::<P, B>(Op::PublicInit, p)? != self.parameters().public_bytes {
            return Err(P::invalid());
        }
        Ok(())
    }
    fn attestation_digest<P: Profile<B>, B: Backends>(
        &mut self,
        plan: Pending,
        hash: &mut HashState,
        p: &mut Platform<'_, B>,
    ) -> Result<[u8; DIGEST_BYTES], P::Error> {
        p.crypto
            .digest(Hash::Init, hash, &[], &mut [])
            .map_err(|_| P::invalid())?;
        p.crypto
            .digest(
                Hash::Update,
                hash,
                &self.framing.bytes[plan.hash_prefix.0..plan.hash_prefix.0 + plan.hash_prefix.1],
                &mut [],
            )
            .map_err(|_| P::invalid())?;
        let mut window = [0x00; PUBLIC_HASH_WINDOW_BYTES];
        for offset in (0..self.parameters().public_bytes).step_by(window.len()) {
            if !p.device.progress() {
                return Err(P::cancelled());
            }
            let n = window.len().min(self.parameters().public_bytes - offset);
            if p.crypto
                .stream(
                    Op::Read,
                    self.framing.algorithm,
                    self.crypto,
                    &[],
                    &mut window[..n],
                )
                .map_err(|_| P::invalid())?
                != n
            {
                return Err(P::invalid());
            }
            p.crypto
                .digest(Hash::Update, hash, &window[..n], &mut [])
                .map_err(|_| P::invalid())?;
        }
        p.crypto
            .digest(
                Hash::Update,
                hash,
                &self.framing.bytes[plan.hash_suffix.0..plan.hash_suffix.0 + plan.hash_suffix.1],
                &mut [],
            )
            .map_err(|_| P::invalid())?;
        p.crypto
            .digest(
                Hash::Update,
                hash,
                &self.framing.material[..DIGEST_BYTES],
                &mut [],
            )
            .map_err(|_| P::invalid())?;
        let mut digest = [0x00; DIGEST_BYTES];
        p.crypto
            .digest(Hash::Final, hash, &[], &mut digest)
            .map_err(|_| P::invalid())?;
        Ok(digest)
    }
    // PKE public generation is closed before the P-256 primitive runs.
    fn attest<P: Profile<B>, B: Backends>(
        &mut self,
        at: usize,
        digest: &[u8; DIGEST_BYTES],
        p: &mut Platform<'_, B>,
    ) -> Result<(), P::Error> {
        let mut key = [0x00; PRIVATE_KEY_BYTES];
        let mut signature = [0x00; MAX_ES256_SIGNATURE_BYTES + 1];
        let result = (|| {
            P::key(&mut key, p)?;
            p.crypto
                .p256_sign(
                    &key,
                    digest,
                    (&mut signature[..RAW_SIGNATURE_BYTES]).try_into().unwrap(),
                )
                .map_err(|_| P::invalid())?;
            let n = der_signature(&mut signature, RAW_SIGNATURE_BYTES).map_err(|_| P::invalid())?;
            // A P-256 DER signature is at most 72 bytes, so its CBOR
            // byte-string header occupies one or two bytes.
            let count = n + if n < CBOR_INLINE_LENGTH_LIMIT { 1 } else { 2 };
            let end = self.framing.length;
            if end + count > FRAMING_BYTES {
                return Err(P::invalid());
            }
            self.framing.bytes.copy_within(at..end, at + count);
            Encoder::new(&mut self.framing.bytes[at..at + count])
                .bytes(&signature[..n])
                .finish()
                .map_err(|_| P::invalid())?;
            self.framing.length += count;
            self.framing.certificate_at += count;
            Ok(())
        })();
        p.memory.wipe(&mut key);
        result
    }
    pub fn length(framing: &Framing) -> usize {
        framing.length + framing.generated_length + framing.certificate_length
    }
    pub fn len(&self) -> usize {
        Self::length(self.framing)
    }
    pub fn read<P: Profile<B>, B: Backends>(
        &mut self,
        offset: usize,
        out: &mut [u8],
        p: &mut Platform<'_, B>,
    ) -> Result<(), Sw> {
        if offset != self.framing.emitted
            || !canokey_protocol::response::checked_window(offset, out.len(), self.len())
        {
            return Err(Sw::WRONG_LENGTH);
        }
        let parts = [
            Part {
                source: PartSource::Framing(0),
                length: self.framing.generated_at,
            },
            Part {
                source: PartSource::Generated,
                length: self.framing.generated_length,
            },
            Part {
                source: PartSource::Framing(self.framing.generated_at),
                length: self.framing.certificate_at - self.framing.generated_at,
            },
            Part {
                source: PartSource::Certificate,
                length: self.framing.certificate_length,
            },
            Part {
                source: PartSource::Framing(self.framing.certificate_at),
                length: self.framing.length - self.framing.certificate_at,
            },
        ];
        let count = out.len();
        let mut window = canokey_protocol::response::ReadWindow::new(offset, out);
        for part in parts {
            let (at, dest) = window.take(part.length);
            let n = dest.len();
            if dest.is_empty() {
                continue;
            }
            match part.source {
                PartSource::Generated => {
                    if p.crypto
                        .stream(Op::Read, self.framing.algorithm, self.crypto, &[], dest)
                        .map_err(|_| Sw::UNABLE_TO_PROCESS)?
                        != n
                    {
                        return Err(Sw::UNABLE_TO_PROCESS);
                    }
                }
                PartSource::Certificate => {
                    P::certificate(at as u32, dest, p)?;
                }
                PartSource::Framing(start) => {
                    dest.copy_from_slice(&self.framing.bytes[start + at..start + at + n])
                }
            }
        }
        self.framing.emitted += count;
        Ok(())
    }
    pub fn close<B: Backends>(&mut self, p: &mut Platform<'_, B>) {
        let _ = p
            .crypto
            .stream(Op::Abort, self.framing.algorithm, self.crypto, &[], &mut []);
        p.memory.wipe(&mut self.crypto.bytes);
        self.framing.clear(p.memory);
    }
}
